use std::collections::HashMap;

/// A value that can appear in a nested dictionary.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(String),
    Array(Vec<Value>),
    Dict(HashMap<String, Value>),
}

/// Flattens an arbitrarily nested dictionary into dot-notation keys.
///
/// # Examples
///
/// ```ignore
/// use std::collections::HashMap;
/// let mut inner = HashMap::new();
/// inner.insert("b".to_string(), Value::Int(1));
/// let mut outer = HashMap::new();
/// outer.insert("a".to_string(), Value::Dict(inner));
///
/// let flat = parse_expression(&Value::Dict(outer));
/// assert_eq!(flat.get("a.b"), Some(&Value::Int(1)));
/// ```
pub fn parse_expression(input: &Value) -> HashMap<String, Value> {
    let mut result = HashMap::new();
    flatten_recursive(input, String::new(), &mut result);
    result
}

fn flatten_recursive(value: &Value, prefix: String, result: &mut HashMap<String, Value>) {
    match value {
        Value::Dict(map) => {
            for (key, val) in map {
                let new_key = if prefix.is_empty() {
                    key.clone()
                } else {
                    format!("{}.{}", prefix, key)
                };
                flatten_recursive(val, new_key, result);
            }
        }
        _ => {
            result.insert(prefix, value.clone());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dict(entries: Vec<(&str, Value)>) -> Value {
        Value::Dict(
            entries
                .into_iter()
                .map(|(k, v)| (k.to_string(), v))
                .collect(),
        )
    }

    fn arr(items: Vec<Value>) -> Value {
        Value::Array(items)
    }

    #[test]
    fn test_empty_dict() {
        let input = dict(vec![]);
        let result = parse_expression(&input);
        assert!(result.is_empty());
    }

    #[test]
    fn test_flat_dict() {
        let input = dict(vec![
            ("a", Value::Int(1)),
            ("b", Value::Int(2)),
            ("c", Value::String("hello".to_string())),
        ]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 3);
        assert_eq!(result.get("a"), Some(&Value::Int(1)));
        assert_eq!(result.get("b"), Some(&Value::Int(2)));
        assert_eq!(
            result.get("c"),
            Some(&Value::String("hello".to_string()))
        );
    }

    #[test]
    fn test_one_level_nesting() {
        let input = dict(vec![
            ("name", Value::String("Alice".to_string())),
            (
                "address",
                dict(vec![
                    ("city", Value::String("NYC".to_string())),
                    ("zip", Value::Int(10001)),
                ]),
            ),
        ]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 3);
        assert_eq!(
            result.get("name"),
            Some(&Value::String("Alice".to_string()))
        );
        assert_eq!(
            result.get("address.city"),
            Some(&Value::String("NYC".to_string()))
        );
        assert_eq!(result.get("address.zip"), Some(&Value::Int(10001)));
    }

    #[test]
    fn test_deep_nesting() {
        let input = dict(vec![(
            "a",
            dict(vec![(
                "b",
                dict(vec![(
                    "c",
                    dict(vec![("d", Value::Int(42))]),
                )]),
            )]),
        )]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 1);
        assert_eq!(result.get("a.b.c.d"), Some(&Value::Int(42)));
    }

    #[test]
    fn test_mixed_leaf_types() {
        let input = dict(vec![
            ("null_val", Value::Null),
            ("bool_val", Value::Bool(true)),
            ("int_val", Value::Int(-5)),
            ("float_val", Value::Float(3.14)),
            ("str_val", Value::String("x".to_string())),
            ("arr_val", arr(vec![Value::Int(1), Value::Int(2)])),
        ]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 6);
        assert_eq!(result.get("null_val"), Some(&Value::Null));
        assert_eq!(result.get("bool_val"), Some(&Value::Bool(true)));
        assert_eq!(result.get("int_val"), Some(&Value::Int(-5)));
        assert_eq!(result.get("float_val"), Some(&Value::Float(3.14)));
        assert_eq!(
            result.get("str_val"),
            Some(&Value::String("x".to_string()))
        );
        assert_eq!(
            result.get("arr_val"),
            Some(&arr(vec![Value::Int(1), Value::Int(2)]))
        );
    }

    #[test]
    fn test_array_values_are_preserved_not_flattened() {
        let input = dict(vec![(
            "items",
            arr(vec![
                dict(vec![("id", Value::Int(1))]),
                dict(vec![("id", Value::Int(2))]),
            ]),
        )]);
        let result = parse_expression(&input);
        // Arrays are leaf nodes — their contents are NOT traversed.
        assert_eq!(result.len(), 1);
        match result.get("items").unwrap() {
            Value::Array(v) => assert_eq!(v.len(), 2),
            other => panic!("expected Array, got {:?}", other),
        }
    }

    #[test]
    fn test_multiple_nested_branches() {
        let input = dict(vec![
            (
                "db",
                dict(vec![
                    ("host", Value::String("localhost".to_string())),
                    ("port", Value::Int(5432)),
                ]),
            ),
            (
                "cache",
                dict(vec![
                    ("host", Value::String("redis".to_string())),
                    ("port", Value::Int(6379)),
                    ("ttl", Value::Int(300)),
                ]),
            ),
        ]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 5);
        assert_eq!(
            result.get("db.host"),
            Some(&Value::String("localhost".to_string()))
        );
        assert_eq!(result.get("db.port"), Some(&Value::Int(5432)));
        assert_eq!(
            result.get("cache.host"),
            Some(&Value::String("redis".to_string()))
        );
        assert_eq!(result.get("cache.port"), Some(&Value::Int(6379)));
        assert_eq!(result.get("cache.ttl"), Some(&Value::Int(300)));
    }

    #[test]
    fn test_nested_empty_dicts_are_omitted() {
        let input = dict(vec![
            ("a", Value::Int(1)),
            ("b", dict(vec![])),
        ]);
        let result = parse_expression(&input);
        // An empty nested dict produces no keys under its prefix.
        assert_eq!(result.len(), 1);
        assert_eq!(result.get("a"), Some(&Value::Int(1)));
    }

    #[test]
    fn test_keys_with_special_characters() {
        let input = dict(vec![(
            "user-settings",
            dict(vec![(
                "font.size",
                Value::Int(14),
            )]),
        )]);
        let result = parse_expression(&input);
        // The function uses `.` as the separator; keys containing dots
        // will produce ambiguous paths (this is expected behavior).
        assert_eq!(result.len(), 1);
        assert_eq!(result.get("user-settings.font.size"), Some(&Value::Int(14)));
    }

    #[test]
    fn test_deeply_nested_five_levels() {
        let input = dict(vec![(
            "l1",
            dict(vec![(
                "l2",
                dict(vec![(
                    "l3",
                    dict(vec![(
                        "l4",
                        dict(vec![("l5", Value::Bool(false))]),
                    )]),
                )]),
            )]),
        )]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 1);
        assert_eq!(result.get("l1.l2.l3.l4.l5"), Some(&Value::Bool(false)));
    }

    #[test]
    fn test_non_dict_root_returns_single_entry() {
        // A non-dict root is a degenerate case: one empty-prefix entry.
        let input = Value::Int(99);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 1);
        assert_eq!(result.get(""), Some(&Value::Int(99)));
    }

    #[test]
    fn test_sibling_dicts_at_same_level() {
        let input = dict(vec![
            (
                "left",
                dict(vec![("val", Value::Int(10))]),
            ),
            (
                "right",
                dict(vec![("val", Value::Int(20))]),
            ),
        ]);
        let result = parse_expression(&input);
        assert_eq!(result.len(), 2);
        assert_eq!(result.get("left.val"), Some(&Value::Int(10)));
        assert_eq!(result.get("right.val"), Some(&Value::Int(20)));
    }
}

